const PUNJABI_STATS=[{label:"Speakers Worldwide",value:"~125 Million"},{label:"Language Family",value:"Indo-Aryan"},{label:"Script",value:"Gurmukhi"},{label:"Primary Region",value:"Punjab"}],PUNJABI_GREETING={gurmukhi:"ਸਤ ਸ੍ਰੀ ਅਕਾਲ",transliteration:"Sat Srī Akāl",meaning:"The standard Punjabi greeting, literally 'Truth is the timeless (immortal) one' — rooted in Sikh tradition and used universally as 'hello' and 'goodbye' by Punjabi speakers of all backgrounds.",folkVariant:{gurmukhi:"ਸਸਰੀਕਾਲ",transliteration:"Sasrīkāl",meaning:"A shortened, casual everyday contraction of Sat Sri Akal, commonly used in informal daily conversation."},note:"Punjabi (pa-IN) is supported as a Text-to-Speech voice in many modern browsers. If a Punjabi voice isn't installed on your device, playback will automatically fall back to the closest available Hindi (Devanagari-script) voice as an approximation."},PUNJABI_WORDS=[{gurmukhi:"ਪਾਣੀ",translit:"Pāṇī",meaning:"Water",note:"Shares its Indo-Aryan root with Hindi 'pani' and other regional languages."},{gurmukhi:"ਵਧੀਆ",translit:"Vadhīā",meaning:"Good / Great",note:"One of the most commonly used Punjabi words for expressing approval or satisfaction."},{gurmukhi:"ਘਰ",translit:"Ghar",meaning:"House / Home",note:"Common Indo-Aryan vocabulary shared widely across North Indian languages."},{gurmukhi:"ਮਾਂ",translit:"Māṁ",meaning:"Mother",note:"Pronounced with a nasalized vowel, marked by the bindi in Gurmukhi script."},{gurmukhi:"ਬਾਪੂ",translit:"Bāpū",meaning:"Father",note:"An affectionate, widely used Punjabi term for father, distinct in tone from more formal Hindi terms."},{gurmukhi:"ਕਿੱਦਾਂ",translit:"Kiddāṁ",meaning:"How / How's it going",note:"A distinctly Punjabi conversational opener, roughly 'how are things' — not a direct Hindi calque."},{gurmukhi:"ਖਾਣਾ",translit:"Khāṇā",meaning:"Food / To eat",note:"Cognate with Hindi 'khana', reflecting shared Indo-Aryan roots."},{gurmukhi:"ਦਿਨ",translit:"Din",meaning:"Day",note:"Common Indo-Aryan vocabulary tracing back to Sanskrit 'dina'."},{gurmukhi:"ਸ਼ੁਕਰੀਆ",translit:"Shukrīā",meaning:"Thank you",note:"Borrowed from Persian/Urdu, reflecting centuries of Persianate influence on spoken Punjabi."},{gurmukhi:"ਜਲਦੀ",translit:"Jaldī",meaning:"Quickly",note:"Shared with Hindi and neighboring Indo-Aryan languages, used identically in everyday Punjabi speech."}],PUNJABI_SCRIPT={intro:"Punjabi in India is written in the Gurmukhi script, developed and standardized in the 16th century under the second Sikh Guru, Guru Angad Dev Ji, to record the hymns of the Sikh Gurus. Gurmukhi is also a distinct tonal-marking script, using diacritics to represent Punjabi's unique tonal system — a feature uncommon among Indo-Aryan languages.",facts:[{title:"Guru Angad Dev Ji's Standardization",detail:"Gurmukhi was systematized in the 16th century specifically to record Sikh scripture, most notably the Guru Granth Sahib, giving the script deep religious and cultural significance."},{title:"Tonal System",detail:"Punjabi is one of the few Indo-Aryan languages with a phonemic tone system; Gurmukhi uses specific consonants and diacritics to indicate rising, falling, and level tones."},{title:"Shahmukhi Counterpart",detail:"In Pakistani Punjab, Punjabi is more commonly written in the Perso-Arabic-derived Shahmukhi script, meaning the same spoken language today has two major written traditions across the India-Pakistan border."}]},PUNJABI_CLASSIFICATION={family:"Indo-European → Indo-Iranian → Indo-Aryan → Northwestern Zone",siblings:["Hindi","Urdu","Saraiki","Dogri"],note:"Punjabi belongs to the Northwestern group of Indo-Aryan languages, sharing deep historical roots with Hindi and Urdu while developing its own distinct grammar, vocabulary, and — uniquely among major Indo-Aryan languages — a phonemic tone system."},PUNJABI_REGIONS={intro:"Punjabi is the majority language of the Indian state of Punjab and is also widely spoken across Punjab, Pakistan, as well as in large diaspora communities in the UK, Canada, and beyond.",areas:["Punjab (India)","Chandigarh","Haryana (border districts)","Delhi NCR","Punjab (Pakistan)","United Kingdom (diaspora)","Canada (diaspora)"]},PUNJABI_CULTURE=[{title:"Gurbani & Sikh Scripture",desc:"The Guru Granth Sahib, Sikhism's central scripture, is composed largely in Punjabi (alongside other regional languages) and written in Gurmukhi, making the language deeply tied to Sikh religious life."},{title:"Punjabi Folk Music & Bhangra",desc:"Punjabi's rich tradition of harvest songs, boliyan (folk verses), and the energetic Bhangra dance form have made Punjabi music one of the most globally recognizable South Asian musical traditions."},{title:"Punjabi Cinema (Pollywood)",desc:"A thriving Punjabi-language film industry produces movies, music, and web content that keeps the language vibrant across both Indian and diaspora audiences."},{title:"Sufi & Classical Poetry",desc:"Punjabi has a centuries-old poetic tradition, including the romantic epic Heer Ranjha and the mystic verses of Punjabi Sufi poets, which remain widely read and sung today."}],PUNJABI_REFERENCES=[{text:"Bhatia, Tej K. Punjabi: A Cognitive-Descriptive Grammar. Routledge, 1993.",url:"https://www.routledge.com/"},{text:"Census of India — Statement of Language and Mother Tongue Strength.",url:"https://censusindia.gov.in/"},{text:"Shackle, Christopher. A Guru Nanak Glossary. School of Oriental and African Studies, 1995.",url:"https://www.soas.ac.uk/"},{text:"People's Linguistic Survey of India (PLSI) — Punjabi Volume.",url:"https://peopleslinguisticsurvey.org/"}];